  fab_exception_list_helper: {
    zh: `「隐藏网站」在全局显示时隐藏悬浮球；「显示网站」在全局隐藏时显示悬浮球。不带斜杠和协议的条目按主机名匹配，*.example.com 含该域名及子域名；带路径或协议的条目仍支持星号(*)。多个网址用换行或逗号分隔。`,
    en: `Hidden sites hide the button while it is shown globally. Shown sites keep it visible while it is hidden globally. Entries without a slash or protocol match the hostname; *.example.com includes that domain and its subdomains. Entries with a path or protocol still support *. Separate URLs with newlines or commas.`,
    zh_TW: `「隱藏網站」在全域顯示時隱藏懸浮球；「顯示網站」在全域隱藏時顯示懸浮球。沒有斜線和協定的項目依主機名稱比對，*.example.com 含該網域及子網域；帶路徑或協定的項目仍支援星號 (*)。多個網址用換行或逗號分隔。`,
    ja: `「隠すサイト」はグローバル表示中にボタンを隠し、「表示するサイト」はグローバル非表示中にボタンを表示します。スラッシュもプロトコルもない項目はホスト名で比較し、*.example.com はそのドメインとサブドメインに一致します。パスやプロトコルを含む項目は引き続き * を使えます。URL は改行またはカンマで区切ります。`,
    ko: `「숨길 사이트」는 전역 표시 중 버튼을 숨기고, 「표시할 사이트」는 전역 숨김 중 버튼을 표시합니다. 슬래시와 프로토콜이 없는 항목은 호스트 이름으로 비교하며, *.example.com 은 해당 도메인과 하위 도메인에 맞습니다. 경로나 프로토콜이 있는 항목은 * 를 계속 쓸 수 있습니다. URL은 줄바꿈 또는 쉼표로 구분합니다.`,
    tr: `「Gizlenecek siteler」 düğme genel olarak gösterilirken onu gizler. 「Gösterilecek siteler」 düğme genel olarak gizlenirken onu gösterir. Eğik çizgi veya protokol içermeyen girdiler ana makine adıyla eşleşir; *.example.com o alan adını ve alt alan adlarını kapsar. Yol veya protokol içeren girdiler * kullanmaya devam eder. Adresleri satır sonu veya virgülle ayırın.`,
    vi: "“Trang bị ẩn” ẩn nút khi nút đang hiện toàn cục. “Trang vẫn hiện” giữ nút khi nó đang ẩn toàn cục. Mục không có dấu / hoặc giao thức được so theo tên máy; *.example.com gồm tên miền đó và tên miền con. Mục có đường dẫn hoặc giao thức vẫn dùng *. Ngăn URL bằng xuống dòng hoặc dấu phẩy.",
  },
